// Mirrors find_column() in scripts/clean_data.py: raw incoming CSVs
// have real headers like 'Full Name', 'Phone Number', 'email_id' --
// not consistent snake_case -- so matching must be case/space
// insensitive or it silently misses 2 of the 3 known source formats.

const NAME_ALIASES = ['name', 'full_name', 'fullname', 'candidate_name', 'worker_name', 'person_name'];
const EMAIL_ALIASES = ['email', 'email_address', 'email_id', 'mail'];
const PHONE_ALIASES = ['phone', 'phone_number', 'mobile', 'mobile_number', 'contact', 'contact_number'];

function findField(row, aliases) {
  const keyMap = {};
  for (const k of Object.keys(row)) {
    keyMap[k.trim().toLowerCase().replace(/\s+/g, '_')] = k;
  }
  for (const alias of aliases) {
    if (keyMap[alias] !== undefined && row[keyMap[alias]]) return row[keyMap[alias]];
  }
  return null;
}

return items.map(item => {
  const row = item.json;
  const rawName = findField(row, NAME_ALIASES) || '';
  const rawEmail = findField(row, EMAIL_ALIASES) || '';
  const rawPhone = findField(row, PHONE_ALIASES) || '';

  const emailNormalized = rawEmail ? String(rawEmail).toLowerCase().trim() : null;
  const phoneDigits = String(rawPhone).replace(/\D/g, '');
  const phoneNormalized = phoneDigits ? phoneDigits.slice(-10) : null;

  return {
    json: {
      candidate_name: String(rawName).trim(),
      raw_email: rawEmail,
      raw_phone: rawPhone,
      email_normalized: emailNormalized,
      phone_normalized: phoneNormalized,
    }
  };
});

